  'cs.rubrics_help': 'तुमचे स्वतःचे गुणांकन मापदंड. तुम्ही प्रशिक्षण देत असलेल्या खेळांचे प्रमाणित मापदंड (FIFA, ICC, ऑलिम्पिक …) तुमच्यासाठी जोडले जातात — ते बदला, वाढवा किंवा संग्रहित करा. एक रुब्रिक अनेक खेळांना लागू होऊ शकते, आणि एका खेळाची अनेक रुब्रिक असू शकतात. प्रत्येक गुण ज्या आवृत्तीत दिला त्यासोबत राहतो, आणि वेगवेगळ्या मापदंडांचे गुण कधीही मिसळले जात नाहीत किंवा अधिकृत आकडेवारीत बदलले जात नाहीत.',
