  'setup.step.legal.w': 'हे करार आणि चलनांवर दिसतात. तुमचा GST, VAT किंवा कर क्रमांक जोडा म्हणजे चलने पहिल्या दिवसापासून वैध असतील.',
  'setup.step.contact.t': 'संपर्क तपशील जोडा',
  'setup.step.contact.w': 'कुटुंबे आणि प्रायोजक तुमच्याशी संपर्क साधू शकतील असा ईमेल किंवा फोन नंबर.',
  'setup.step.staff.t': 'तुमच्या प्रशिक्षकांना आणि अ‍ॅडमिनना आमंत्रित करा',
  'setup.step.staff.w': 'प्रत्येक व्यक्तीला भूमिका द्या म्हणजे त्यांना फक्त हवे तेच दिसेल.',
  'setup.step.structure.t': 'तुमचा पहिला संघ तयार करा',
  'setup.step.structure.w': 'संघांमध्ये तुमची यादी, उपलब्धता आणि सामने असतात.',
  'setup.step.structure_academy.t': 'तुमचा पहिला कार्यक्रम तयार करा',
  'setup.step.structure_academy.w': 'कार्यक्रमांमध्ये वयोगट, वेळापत्रक आणि शुल्क असते ज्यासाठी कुटुंबे अर्ज करतात.',
  'setup.step.season.t': 'हंगाम सेट करा',
  'setup.step.season.w': 'हंगाम तुमचे कार्यक्रम, संघ आणि हजेरी यांना तारखा देतो.',
  'setup.step.people.t': 'तुमचे लोक आणा',
  'setup.step.people.w': 'TeamSnap, SportsEngine किंवा स्प्रेडशीटमधून तुमची यादी आयात करा. जतन करण्यापूर्वी तुम्हाला सर्व काही दिसते.',
  'setup.step.first_transaction.t': 'तुमचा पहिला इव्हेंट किंवा सामना चालवा',
  'setup.step.first_transaction.w': 'तुमचे सदस्य पाहू शकतील आणि प्रतिसाद देऊ शकतील असे काहीतरी तयार करा.',
  'setup.step.first_transaction_academy.t': 'तुमचे पहिले शुल्क आकारा',
  'setup.step.first_transaction_academy.w': 'पहिले शुल्क किंवा चलन तुमचा पैशांचा प्रवाह सुरुवातीपासून शेवटपर्यंत काम करतो हे सिद्ध करते.',
  'setup.step.venue.t': 'तुमचे स्थळ जोडा',
  'setup.step.venue.w': 'नाव, पत्ता आणि येथे होणारे खेळ.',
  'setup.step.courts.t': 'तुमचे कोर्ट, मैदाने किंवा खोल्या जोडा',
  'setup.step.courts.w': 'प्रत्येकाची स्वतःची क्षमता आणि स्लॉट कालावधी असतो.',
  'setup.step.hours.t': 'तुमच्या उघडण्याच्या वेळा ठरवा',
  'setup.step.hours.w': 'तुम्ही उघडे असतानाच लोक बुक करू शकतात.',
  'setup.step.rates.t': 'तुमचे ताशी दर ठरवा',
  'setup.step.rates.w': 'किंमतींमध्ये कर समाविष्ट आहे. पीक आणि ऑफ-पीक नियम नंतर जोडता येतात.',
  'setup.step.first_transaction_venue.t': 'तुमची पहिली बुकिंग घ्या',
  'setup.step.first_transaction_venue.w': 'स्वतः एक चाचणी बुकिंग करा, किंवा तुमचे स्थळ पेज शेअर करा.',
  'setup.step.event.t': 'तुमचा इव्हेंट तयार करा',
  'setup.step.event.w': 'खेळ, तारखा, स्थळ आणि स्वरूप.',
  'setup.step.open.t': 'प्रवेशिकांसाठी खुले करा',
  'setup.step.open.w': 'इव्हेंट खुले झाल्यावरच संघ प्रवेश करू शकतात.',
  'setup.step.first_transaction_organiser.t': 'तुमचे पहिले सामने नियोजित करा',
  'setup.step.first_transaction_organiser.w': 'वेळापत्रक तुमच्यासाठी रेफरी आणि संघांच्या टकरावांची तपासणी करते.',
  'setup.step.profile.t': 'तुमची प्रशिक्षक प्रोफाइल सेट करा',
  'setup.step.profile.w': 'तुमचे शीर्षक, विशेषज्ञता आणि वेळा, म्हणजे लोक तुम्हाला शोधून बुक करू शकतील.',
  'setup.step.team.t': 'तुमचा संघ तयार करा',
  'setup.step.team.w': 'तुमची यादी, उपलब्धता आणि वेळापत्रक येथे असते.',
  'setup.step.first_transaction_coach.t': 'तुमच्या खेळाडूंना आमंत्रित करा',
  'setup.step.first_transaction_coach.w': 'तुम्ही ओळखता त्यांना आमंत्रित करा, किंवा संस्थेच्या कार्यक्षेत्रातून संपूर्ण यादी आणा.',
